#!/usr/bin/env python3
"""FALLGUY stunt script for one run (generated by `loop.py init` from scripts/stunt_template.py).

Brief:      __FALLGUY_BRIEF__
Generated:  __FALLGUY_GENERATED_AT__

There are no stunt types. plan.json's `stunt` holds Argon's choreography for the brief as generic phases
(hold, move, jump, fall, air, land) plus the tunables the loop changes; the engine interprets the phases.
Performer: always the Unitree H1 (engine.performer, composed as in barrel_roll.py).

CLI (reference/contracts.md, "Generated stunt script CLI"):
  python stunt_<slug>_<ts>.py --plan plan.json --params waves/wave01/c1/params.json --out-dir waves/wave01/c1 \
      [--render] [--duration 6] [--fps 30] [--size 720x1280] [--camera match_follow|match|hero|side] [--hud] \
      [--preview-still preview.png] [--check]

  default          simulate + Gate-1 metrics: out-dir/{scene.xml, trajectory.npz, events.json, metrics.json}
  --render         also out-dir/video.mp4 at exactly --duration seconds (default plan.duration_sec)
  --preview-still  one still of the scene at the start pose (director's `match` camera unless --camera), then exit
  --check          build the model and step it for 0.5 s, print OK, exit 0

  --size defaults to the media aspect (plan.source width/height: portrait 720x1280, else 1280x720).
  --camera defaults to params.camera, else plan.stunt.default_camera, else match_follow.
  Any failure writes out-dir/metrics.json with "ok": false and the error, and exits 1.
"""
import argparse
import copy
import json
import os
import sys
import tempfile
import traceback

SCRIPTS_DIR = "__FALLGUY_SCRIPTS_DIR__"
BRIEF = "__FALLGUY_BRIEF__"
GENERATED_AT = "__FALLGUY_GENERATED_AT__"

if SCRIPTS_DIR.startswith("__FALL" + "GUY_"):      # the raw template, run in place (tests)
    SCRIPTS_DIR = os.path.dirname(os.path.abspath(__file__))
if SCRIPTS_DIR not in sys.path:
    sys.path.insert(0, SCRIPTS_DIR)


# ============================================================================ the hook: edit to change the motion
def choreography(plan, params):
    """Return the motion engine.sim.run performs. Default: plan.stunt with this candidate's tunables applied.

    The result is a stunt dict {"summary", "start", "phases", "target", ...}; phase kinds and fields are in
    reference/contracts.md ("Choreography phases"). Edit the dict, e.g.:

        s = P.apply(plan, params)
        s["phases"][1]["lean_scale"] = 0.7                                    # change a phase
        s["phases"].insert(2, {"kind": "hold", "name": "look", "duration": 0.4, "pose": "brace"})  # add one
        return s

    For motion the phase kinds can't express, return a custom motion object instead of a dict; its interface
    is documented in engine.sim.run. Numbers the loop should tune belong in plan.stunt.tunables, not here.
    """
    from engine import params as P
    return P.apply(plan, params)


# ============================================================================ glue (no stunt-specific physics)
CHECK_SECONDS = 0.5
DEFAULT_DURATION = 6.0


class _Fail(Exception):
    """A failure with a plain message (no traceback)."""


def log(msg):
    sys.stderr.write(msg + "\n")
    sys.stderr.flush()


def read_json(path, what):
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        raise _Fail(f"{what} not found: {path}") from None
    except json.JSONDecodeError as e:
        raise _Fail(f"{what} is not valid JSON ({path}: {e})") from None


def write_json(path, obj):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(obj, f, indent=1)
    os.replace(tmp, path)


def parse_size(text):
    try:
        w, h = (int(v) for v in str(text).lower().replace("*", "x").split("x"))
    except ValueError:
        raise _Fail(f"--size must be WxH, e.g. 720x1280 (got {text!r})") from None
    if not (16 <= w <= 7680 and 16 <= h <= 7680):
        raise _Fail(f"--size {w}x{h} is out of range (16-7680 px per side)")
    return w, h


def default_size(plan):
    """Portrait media (plan.source height > width) renders 720x1280, anything else 1280x720."""
    src = plan.get("source") if isinstance(plan.get("source"), dict) else {}
    try:
        w, h = float(src.get("width") or 0), float(src.get("height") or 0)
    except (TypeError, ValueError):
        w = h = 0.0
    return (720, 1280) if w > 0 and h > w else (1280, 720)


def default_camera(plan, raw_params):
    for cam in ((raw_params or {}).get("camera"), (plan.get("stunt") or {}).get("default_camera")):
        if isinstance(cam, str) and cam.strip():
            return cam.strip()
    return "match_follow"


def check_camera(cam):
    from engine import params as P
    cams = list(getattr(P, "CAMERAS", ["match_follow", "match", "hero", "side"]))
    if cam not in cams:
        raise _Fail(f"unknown camera {cam!r} (one of {', '.join(cams)})")
    return cam


def motion(plan, params):
    """choreography()'s answer, checked: a stunt dict needs a non-empty phases list."""
    m = choreography(plan, params)
    if m is None:
        raise _Fail("choreography() returned None; return a stunt dict (default P.apply(plan, params)) or a motion object")
    if isinstance(m, dict) and not (isinstance(m.get("phases"), list) and m["phases"]):
        raise _Fail("choreography() returned a stunt dict without phases")
    return m


def start_only(m):
    """The stunt reduced to a short hold at its start pose (for the preview still); custom motion as is."""
    if not isinstance(m, dict):
        return m
    s = copy.deepcopy(m)
    first = s["phases"][0] if isinstance(s["phases"][0], dict) else {}
    pose = first.get("pose") if first.get("kind") == "hold" and first.get("pose") else "stand"
    s["phases"] = [{"kind": "hold", "name": "preview", "duration": 0.1, "pose": pose}]
    return s


def do_check(plan, params, m):
    """Run the choreography through engine.sim (in a scratch dir), then rebuild the written scene.xml as
    engine.render will and step it for 0.5 s from the start pose."""
    import mujoco
    import numpy as np
    from engine import sim
    with tempfile.TemporaryDirectory(prefix="fallguy_check_") as tmp:
        ev = sim.run(plan, params, tmp, choreography=m, log=log)
        q = np.load(os.path.join(tmp, "trajectory.npz"))["qpos"]
        if len(q) == 0 or not np.all(np.isfinite(q)):
            raise _Fail("the simulated trajectory is empty or non-finite")
        model = mujoco.MjModel.from_xml_path(os.path.join(tmp, "scene.xml"))
    data = mujoco.MjData(model)
    data.qpos[:] = q[0]
    n = int(round(CHECK_SECONDS / model.opt.timestep))
    for _ in range(n):
        mujoco.mj_step(model, data)
    if not np.all(np.isfinite(data.qpos)):
        raise _Fail("the model state became non-finite during the 0.5 s check")
    phases = ", ".join(f"{p.get('name')}:{p.get('kind')}" for p in (ev or {}).get("phases") or [])
    log(f"check: nq={model.nq}, ngeom={model.ngeom}, {len(q)} sim steps, phases [{phases}], "
        f"t_finish {(ev or {}).get('t_finish')}")


def do_preview(plan, params, m, out_png, camera, size):
    """One still of the scene with the H1 at the stunt's start pose."""
    import numpy as np
    from engine import render, sim
    with tempfile.TemporaryDirectory(prefix="fallguy_preview_") as tmp:
        sim.run(plan, params, tmp, choreography=start_only(m), log=log)
        q0 = np.load(os.path.join(tmp, "trajectory.npz"))["qpos"][0].copy()
        os.makedirs(os.path.dirname(out_png) or ".", exist_ok=True)
        path = render.render_still(os.path.join(tmp, "scene.xml"), q0, plan, out_png, camera=camera, size=size)
    log(f"preview: {path or out_png} ({size[0]}x{size[1]}, {camera} camera)")


def do_simulate(plan, params, m, out_dir, candidate_id):
    """engine.sim.run, then engine.metrics.compute (Gate 1 via gates.evaluate_gate1) -> metrics.json."""
    from engine import metrics as M
    from engine import sim
    sim.run(plan, params, out_dir, choreography=m, log=log)
    met = M.compute(plan, params, out_dir)
    if "passed" not in (met.get("gate1") or {}) or "stunt_score" not in (met.get("score") or {}):
        import gates
        met = gates.evaluate_gate1(met) or met
    met.setdefault("candidate_id", candidate_id)
    met.setdefault("ok", True)
    met.setdefault("error", None)
    write_json(os.path.join(out_dir, "metrics.json"), met)
    return met


def do_render(plan, params, out_dir, duration, fps, size, camera, hud, met):
    from engine import render
    j = lambda name: os.path.join(out_dir, name)
    inputs = {"scene_xml": j("scene.xml"), "trajectory": j("trajectory.npz"), "events": j("events.json"),
              "plan": plan, "params": params, "metrics": met}
    video = j("video.mp4")
    if os.path.exists(video):
        os.remove(video)
    render.render_video(inputs, video, duration, fps=fps, size=size, camera=camera, hud=hud)
    if not os.path.isfile(video):
        raise _Fail(f"render finished without writing {video}")
    log(f"render: {video} ({duration:g} s @ {fps} fps, {size[0]}x{size[1]}, {camera} camera)")


def write_failure(out_dir, candidate_id, error):
    try:
        os.makedirs(out_dir, exist_ok=True)
        write_json(os.path.join(out_dir, "metrics.json"),
                   {"candidate_id": candidate_id, "ok": False, "error": error, "sim": None, "gate1": None,
                    "score": None})
    except Exception as e:      # still exit 1
        log(f"could not write metrics.json: {e}")


def parse_args(argv):
    ap = argparse.ArgumentParser(description=f"FALLGUY stunt script: {BRIEF}")
    ap.add_argument("--plan", required=True, help="plan.json")
    ap.add_argument("--params", required=True, help="candidate params.json")
    ap.add_argument("--out-dir", required=True, help="candidate dir: scene.xml, trajectory.npz, events.json, metrics.json")
    ap.add_argument("--render", action="store_true", help="also render out-dir/video.mp4")
    ap.add_argument("--duration", type=float, default=None, help="video length in s (default plan.duration_sec)")
    ap.add_argument("--fps", type=int, default=30)
    ap.add_argument("--size", default=None, help="WxH (default from the media aspect)")
    ap.add_argument("--camera", default=None, help="match_follow|match|hero|side (default params.camera)")
    ap.add_argument("--hud", action="store_true", help="overlay the HUD")
    ap.add_argument("--preview-still", default=None, metavar="PATH", help="render one still at the start pose, then exit")
    ap.add_argument("--check", action="store_true", help="build and step 0.5 s, print OK")
    return ap.parse_args(argv)


def main(argv=None):
    a = parse_args(argv)
    out_dir = os.path.abspath(a.out_dir)
    candidate_id = None
    try:
        from engine import params as P
        plan = read_json(a.plan, "plan")
        raw = read_json(a.params, "params")
        if not isinstance(plan, dict) or not isinstance(raw, dict):
            raise _Fail("plan.json and params.json must each be a JSON object")
        if not isinstance(plan.get("stunt"), dict):
            raise _Fail("plan.json has no stunt object")
        candidate_id = raw.get("id")
        params = P.clamp(raw, plan)
        size = parse_size(a.size) if a.size else default_size(plan)
        if not 1 <= a.fps <= 240:
            raise _Fail(f"--fps {a.fps} is out of range (1-240)")
        m = motion(plan, params)

        if a.check:
            do_check(plan, params, m)
            print("OK", flush=True)
            return 0
        if a.preview_still:
            do_preview(plan, params, m, os.path.abspath(a.preview_still), check_camera(a.camera or "match"), size)
            return 0

        camera = check_camera(a.camera or default_camera(plan, raw)) if a.render else None
        os.makedirs(out_dir, exist_ok=True)
        met = do_simulate(plan, params, m, out_dir, candidate_id)
        g1 = met.get("gate1") or {}
        log(f"metrics: gate1 {'PASS' if g1.get('passed') else 'FAIL'} "
            f"score {(met.get('score') or {}).get('stunt_score')} failures {g1.get('failures') or []}")
        if a.render:
            duration = a.duration if a.duration is not None else float(plan.get("duration_sec") or DEFAULT_DURATION)
            if not 0.5 <= duration <= 120:
                raise _Fail(f"--duration {duration:g} is out of range (0.5-120 s)")
            do_render(plan, params, out_dir, duration, a.fps, size, camera, a.hud, met)
        return 0
    except BaseException as e:      # noqa: BLE001 - every failure becomes metrics.json ok:false + exit 1
        if isinstance(e, SystemExit) and e.code in (0, None):
            raise
        if isinstance(e, KeyboardInterrupt):
            err = "interrupted"
        elif isinstance(e, _Fail):
            err = str(e)
        else:
            err = f"{type(e).__name__}: {e}"
            traceback.print_exc()
        log(f"error: {err}")
        write_failure(out_dir, candidate_id, err)
        return 1


if __name__ == "__main__":
    sys.exit(main())
